n │ * ├─────────┼───────┤ * │ alice │ alice │ * └─────────┴───────┘ */ trim_start() { return this.strip_chars_start(); } /** * Converts string to uppercase. * @returns ColumnExpression * @example * >>> const df = $df.data({ text: ["alice"] }) * >>> df.with_columns($df.col("text").str.upper().alias("upper")) * shape: (1, 2) * ┌───────┬───────┐ * │ text │ upper │ * ├───────┼───────┤ * │ alice │ ALICE │ * └───────┴───────┘ */ upper() { return this._deriveString((str) => str.toUpperCase()); } /** * Pads start of string with zeros to target width. * @param width Minimum resulting string width. * @returns ColumnExpression * @example * >>> const df = $df.data({ num: ["42"] }) * >>> df.with_columns($df.col("num").str.zfill(5).alias("padded")) * shape: (1, 2) * ┌─────┬────────┐ * │ num │ padded │ * ├─────┼────────┤ * │ 42 │ 00042 │ * └─────┴────────┘ */ zfill(width: number) { return this._deriveString((str) => str.padStart(width, "0")); } } export class StringExpr extends ExprBase { /** * String namespace accessor for text operations. * @namespace $df.col * @category ColumnExpression * @syntax $df.col(<column_name>).str * @returns StringExprNamespace * @example * >>> df.select($df.col("a").str.len()) */ get str() { return new StringExprNamespace(this
